// The fixture layer (SPEC-platform §10; M11 plan decision 8): 12 boxes of three
// kinds, generated by `generate.ts` (no Blender). It proves that a layer added
// only to a registry reaches the Layers panel, its system group, the URL, the
// loader, the batches and picking; since M12 (plan decision 14) also the graph
// (its system's edge types), tiers (its rules), the info panel (its sections)
// and the sidebar tree (its `byKind` spec). Never shipped: only the test
// registry (`../../registry.ts`) lists it.
import type { KindTiers } from "../../../../../src/graph/types";
import { defineLayer, type PanelChrome, type PanelSection } from "../../../../../src/systems/types";

/** Tier 1: what it meshes with, drives or is driven by. Tier 2: tier 1, then everything meshing with any of those (its gear train). */
const TIERS = {
  t1: {
    steps: [{ follow: ["meshes_with", "drives", "driven by"] }],
    order: "id",
    wording: { label: "linked widgets", button: { text: "Show linked", title: "Show the widgets it meshes with or drives", shown: "Shown" } },
  },
  t2: {
    steps: [{ tier: "t1" }, { follow: "meshes_with", from: "result" }],
    order: "id",
    wording: { label: "gear train", button: { text: "Show the train", title: "Show its whole gear train", shown: "Shown" } },
  },
} as const satisfies KindTiers;

/** The three section types decision 14 names: a text, a links and a grouped-links section. */
const PANEL = [
  { title: "Summary", testId: "summary", render: "text", field: "summary", format: "html" },
  { title: "Meshes with", testId: "meshes", render: "links", edges: "meshes_with", order: "id", empty: "Meshes with nothing." },
  {
    title: "Drive",
    testId: "drive",
    render: "grouped-links",
    groups: [
      { edges: "drives", title: "Drives", testId: "drives", role: "drives" },
      { edges: "driven by", title: "Driven by", testId: "driven-by", role: "is driven by" },
    ],
    order: "id",
    empty: "Drives nothing and is driven by nothing.",
  },
] as const satisfies readonly PanelSection[];

const chrome = (label: string): PanelChrome => ({
  typeLine: () => label,
  badges: () => ["Widgets", label],
  draft: "unreviewed",
  trail: (ctx) => ({ trail: ["Widgets", ctx.name] }),
  common: "when-written",
  unwritten: "all-sections",
});

const kind = <I extends string>(id: I, label: string, many: string, labelPriority: number) =>
  ({ id, label, noun: { one: label.toLowerCase(), many }, labelPriority, tiers: TIERS, panel: PANEL, chrome: chrome(label) }) as const;

export const widgets = defineLayer({
  id: "widgets",
  system: "demo",
  code: "w",
  label: "Widgets",
  ghostOrder: 4,
  // Chosen to clear M10's colour-vision table (re-run by tests/fixture.test.ts): ΔE2000 ≥ 9.9 from every colour it meets under all three visions, 3:1 on the legend, label text 4.5:1 over it.
  colour: { material: "#dd2200", debug: "#dd2200" },
  models: {
    file: "widgets",
    eager: false,
    // M13 plan decision 11: one file per coarse body region (head, thorax, left lower limb), as a big future layer would ship.
    chunking: "region",
    debugManifest: () => import("./models/manifest.json"),
    budgets: { high: { maxMiB: 0.1, targetTris: 144 }, low: { maxMiB: 0.1, targetTris: 144 } },
  },
  // Served by the fixture build only (../../vite.ts), compiled from `content/`.
  contentChunk: "virtual:skeleton-soft-content-widgets",
  defaultSetting: "off",
  // Kind, then assembly (an assembly of one widget needs no level).
  tree: {
    builder: "byKind",
    root: { label: "Widgets", name: "All widgets", order: 3 },
    field: "assembly",
    kinds: [
      { kind: "gear", label: "Gears" },
      { kind: "spring", label: "Springs" },
      { kind: "lever", label: "Levers" },
    ],
    nodeName: (kindLabel: string, assembly: string) => `${kindLabel}: ${assembly}`,
  },
  kinds: [kind("gear", "Gear", "gears", 7), kind("spring", "Spring", "springs", 8), kind("lever", "Lever", "levers", 9)],
});

/** The 12 structures: four of each kind, `widget_<kind>_<n>`. */
export const WIDGET_IDS: readonly string[] = widgets.kinds.flatMap((k) => [1, 2, 3, 4].map((n) => `widget_${k.id}_${n}`));
